        <script>
        (function(){let current=null,previousFocus=null;const backdrop=document.querySelector('.cast-drawer-backdrop');function close(){if(!current)return;current.hidden=true;current=null;if(backdrop)backdrop.hidden=true;document.body.style.overflow='';if(previousFocus&&previousFocus.focus)previousFocus.focus();}
        function open(drawer){if(!drawer)return;close();previousFocus=document.activeElement;current=drawer;drawer.hidden=false;if(backdrop)backdrop.hidden=false;document.body.style.overflow='hidden';drawer.focus();}
        document.addEventListener('click',function(e){const tab=e.target.closest('[data-cast-tab]');if(tab){document.querySelectorAll('[data-cast-tab]').forEach(t=>t.setAttribute('aria-selected',String(t===tab)));document.querySelectorAll('[data-cast-list]').forEach(p=>p.hidden=p.dataset.castList!==tab.dataset.castTab);return;}
        const view=e.target.closest('.cast-view-switch [data-view]');if(view){const panel=view.closest('[data-cast-list]');panel.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===view)));panel.querySelectorAll('[data-content]').forEach(c=>c.hidden=c.dataset.content!==view.dataset.view);return;}
        const roles=e.target.closest('[data-open-cast-drawer]');if(roles){open(document.getElementById('cast-roles-drawer'));return;}
        const assign=e.target.closest('[data-open-assignment]');if(assign){open([...document.querySelectorAll('[data-assignment-drawer]')].find(x=>x.dataset.assignmentDrawer===assign.dataset.openAssignment));return;}
        if(e.target.closest('[data-close-cast-drawer]'))close();
        });document.addEventListener('keydown',function(e){if(e.key==='Escape')close();if(e.key!=='Tab'||!current)return;const items=[...current.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')].filter(x=>x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
        })();
        </script>
        <section class="cast-summary"><?php foreach(['under_review'=>'Under review','callback'=>'Callback','offered'=>'Offered','cast'=>'Cast','not_cast'=>'Not cast'] as $key=>$label):?><article><b><?=(int)$counts[$key]?></b><span><?=$e($label)?></span></article><?php endforeach;?></section>
        <div class="cast-intake-grid"><section class="cast-panel"><header><small>AUDITION INTAKE</small><h3>Reviewed registrations</h3></header><?php if(!$intake):?><p>No linked audition registrations are waiting to be added.</p><?php endif;?><?php foreach($intake as $row):?><form class="cast-candidate" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="action" value="add_intake"><input type="hidden" name="user_id" value="<?=(int)$row['user_id']?>"><input type="hidden" name="submission_id" value="<?=(int)$row['submission_id']?>"><span><b><?=$e((string)$row['person_name'])?></b><small><?=$e((string)$row['opportunity_title'])?> · <?=ucwords(str_replace('_',' ',(string)$row['registration_status']))?></small></span><button type="submit">Add to casting</button></form><?php endforeach;?></section>
        <section class="cast-panel"><header><small>PEOPLE</small><h3>Add existing student</h3></header><?php if($people):?><form class="cast-add" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="action" value="add_person"><select name="user_id" required><option value="">Choose student…</option><?php foreach($people as $p):?><option value="<?=(int)$p['id']?>"><?=$e((string)$p['name'])?> · <?=$e((string)$p['role'])?></option><?php endforeach;?></select><button type="submit">Add student</button></form><?php else:?><p>Every active Student is already represented on the casting board.</p><?php endif;?><p class="cast-help">Registered Students retain normal account and family workflows.</p></section></div>
        <details class="cast-panel cast-manual-add"><summary><b>Add Participant Manually</b><span>No login or membership will be created.</span></summary><form class="cast-decision" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="action" value="add_manual"><?php if($manualProfiles):?><label class="wide">Reuse existing profile<select name="existing_manual_participant_id"><option value="0">Create a new profile</option><?php foreach($manualProfiles as $profile):?><option value="<?=(int)$profile["id"]?>"><?=$e((string)$profile["name"])?></option><?php endforeach;?></select></label><?php endif;?><label>First name<input name="first_name" maxlength="100"></label><label>Last name<input name="last_name" maxlength="100"></label><label>Public display name<input name="display_name" maxlength="190"></label><label>Type<select name="participant_type"><option value="cast">Cast</option><option value="crew">Crew</option><option value="creative">Creative</option><option value="other">Other</option></select></label><label>Character / credit<input name="role_title" maxlength="500"></label><label>Status<select name="casting_status"><option value="under_review">Under review</option><option value="callback">Callback</option><option value="cast">Cast / participating</option><option value="not_cast">Not cast</option><option value="withdrawn">Withdrawn</option></select></label><label class="wide">Biography<textarea name="biography" rows="3" maxlength="5000"></textarea></label><label>Headshot<input type="file" name="headshot" accept="image/jpeg,image/png,image/webp"></label><label>Display order<input type="number" name="display_order" value="0"></label><label><input type="checkbox" name="approve_public_name" value="1"> Approve public name</label><label><input type="checkbox" name="approve_public_biography" value="1"> Approve public biography</label><label><input type="checkbox" name="approve_public_headshot" value="1"> Approve public headshot</label><button type="submit">Add manual participant</button></form></details>
        <section class="cast-board"><header><div><small>WORKING BOARD</small><h2>Casting decisions</h2></div><span><?=count($board)?> students</span></header><?php if(!$board):?><div class="cast-empty compact">Add a reviewed audition or existing Student to begin casting.</div><?php endif;?>
        <?php foreach($board as $r):$groupIds=array_map(static fn(array $g):int=>(int)$g['id'],$r['groups']);?><?php if(($r['identity_type']??'registered')==='manual'):?><article class="cast-card cast-card-manual status-<?=$e((string)$r['casting_status'])?>"><div class="cast-person"><span class="cast-avatar"><?=strtoupper(substr((string)$r['person_name'],0,1))?></span><div><small>MANUAL <?=strtoupper($e((string)$r['participant_type']))?> · NO LOGIN</small><h3><?=$e((string)$r['person_name'])?></h3><p><?=$e((string)($r['role_title']??''))?></p></div></div><form class="cast-decision" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="action" value="update_manual"><input type="hidden" name="record_id" value="<?=(int)$r['id']?>"><label>First name<input name="first_name" value="<?=$e((string)$r['first_name'])?>"></label><label>Last name<input name="last_name" value="<?=$e((string)$r['last_name'])?>"></label><label>Public display name<input name="display_name" value="<?=$e((string)($r['display_name']??''))?>"></label><label>Type<select name="participant_type"><?php foreach(['cast','crew','creative','other'] as $type):?><option value="<?=$type?>"<?=$r['participant_type']===$type?' selected':''?>><?=ucfirst($type)?></option><?php endforeach;?></select></label><label>Character / credit<input name="role_title" value="<?=$e((string)($r['role_title']??''))?>"></label><label>Status<select name="casting_status"><?php foreach(['under_review','callback','offered','cast','not_cast','withdrawn'] as $status):?><option value="<?=$status?>"<?=$r['casting_status']===$status?' selected':''?>><?=ucwords(str_replace('_',' ',$status))?></option><?php endforeach;?></select></label><label class="wide">Biography<textarea name="biography" rows="3"><?=$e((string)($r['biography']??''))?></textarea></label><label>Replace headshot<input type="file" name="headshot" accept="image/jpeg,image/png,image/webp"></label><label>Display order<input type="number" name="display_order" value="<?=(int)$r['display_order']?>"></label><label><input type="checkbox" name="approve_public_name" value="1"<?=$r['approve_public_name']?' checked':''?>> Public name</label><label><input type="checkbox" name="approve_public_biography" value="1"<?=$r['approve_public_biography']?' checked':''?>> Public bio</label><label><input type="checkbox" name="approve_public_headshot" value="1"<?=$r['approve_public_headshot']?' checked':''?>> Public headshot</label><button type="submit">Save manual participant</button></form><div class="cast-manual-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="record_id" value="<?=(int)$r['id']?>"><button name="action" value="archive_manual" type="submit">Archive</button></form><?php if($people):?><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="record_id" value="<?=(int)$r['id']?>"><select name="student_user_id" required><option value="">Transfer to registered Student…</option><?php foreach($people as $p):?><option value="<?=(int)$p['id']?>"><?=$e((string)$p['name'])?></option><?php endforeach;?></select><label><input type="checkbox" name="copy_name" value="1"> Name</label><label><input type="checkbox" name="copy_biography" value="1"> Bio</label><label><input type="checkbox" name="copy_headshot" value="1"> Headshot</label><label><input type="checkbox" name="copy_credit" value="1" checked> Credit</label><button name="action" value="transfer_manual" type="submit">Transfer selected data</button></form><?php endif;?></div></article><?php continue;?><?php endif;?><article class="cast-card status-<?=$e((string)$r['casting_status'])?>"><div class="cast-person"><span class="cast-avatar"><?=strtoupper(substr((string)$r['person_name'],0,1))?></span><div><small><?=$r['opportunity_title']?$e((string)$r['opportunity_title']):'Added from People'?></small><h3><?=$e((string)$r['person_name'])?></h3><p><?=$e((string)$r['account_role'])?><?php if($r['production_membership_id']):?> · <strong>Rostered</strong><?php endif;?><?php if($r['result_communicated_at']):?> · <strong>Result sent</strong><?php endif;?></p></div></div>
        <form class="cast-decision" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="action" value="update"><input type="hidden" name="record_id" value="<?=(int)$r['id']?>"><label>Decision<select name="casting_status"><?php foreach(['under_review'=>'Under review','callback'=>'Callback','offered'=>'Offered','cast'=>'Cast','not_cast'=>'Not cast','withdrawn'=>'Withdrawn'] as $value=>$label):?><option value="<?=$value?>"<?=$r['casting_status']===$value?' selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Character / role<input name="role_title" maxlength="190" value="<?=$e((string)($r['role_title']??''))?>" placeholder="Young Anna, Ensemble, Sven…"></label><label>Track / company note<input name="participation_track" maxlength="100" value="<?=$e((string)($r['participation_track']??''))?>" placeholder="Principal, Ensemble, Dance…"></label><label class="wide">Staff notes<textarea name="staff_notes" rows="2" maxlength="2000" placeholder="Private casting notes…"><?=$e((string)($r['staff_notes']??''))?></textarea></label><button type="submit">Save decision</button></form>
        <div class="cast-communication"><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="action" value="send_result"><input type="hidden" name="record_id" value="<?=(int)$r['id']?>"><span><b>Family communication</b><small><?=in_array($r['casting_status'],['offered','cast','not_cast'],true)?'Explicitly send the current result. Changing the decision above never sends this automatically.':'Set the decision to Offered, Cast, or Not cast before sending.'?></small></span><button type="submit"<?=!in_array($r['casting_status'],['offered','cast','not_cast'],true)?' disabled':''?>><?=$r['result_communicated_at']?'Send updated result':'Send result'?></button></form></div>
        <form class="cast-finalize" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['casting_csrf'])?>"><input type="hidden" name="action" value="finalize"><input type="hidden" name="record_id" value="<?=(int)$r['id']?>"><div><small>PRODUCTION GROUPS</small><div class="cast-groups"><?php if(!$groups):?><em>No active Production Groups yet.</em><?php endif;?><?php foreach($groups as $g):?><label><input type="checkbox" name="group_ids[]" value="<?=(int)$g['id']?>"<?=in_array((int)$g['id'],$groupIds,true)?' checked':''?>><?=$e((string)$g['name'])?></label><?php endforeach;?></div></div><div class="cast-finalize-action"><?php if($r['production_membership_id']):?><span>Roster membership linked</span><?php endif;?><button type="submit"<?=$r['casting_status']!=='cast'?' disabled':''?>><?=$r['production_membership_id']?'Update roster & groups':'Finalize to roster'?></button></div></form></article><?php endforeach;?></section>
        <?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function flash(string $type,string $message):void{$_SESSION['casting_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);exit('Restricted');}
}
